import{$ as e,B as t,o as n,z as r}from"./chunks/framework.BROBN02c.js";var i=JSON.parse(`{"title":"escrcpy-Next × 官方 v3.3.1 功能对齐与超越总计划","description":"","frontmatter":{},"headers":[],"relativePath":"dev/parity-plan.md","filePath":"dev/parity-plan.md","lastUpdated":1795603101000}`),a={name:`dev/parity-plan.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="escrcpy-next-×-官方-v3-3-1-功能对齐与超越总计划" tabindex="-1">escrcpy-Next × 官方 v3.3.1 功能对齐与超越总计划 <a class="header-anchor" href="#escrcpy-next-×-官方-v3-3-1-功能对齐与超越总计划" aria-label="Permalink to &quot;escrcpy-Next × 官方 v3.3.1 功能对齐与超越总计划&quot;">​</a></h1><blockquote><p>本文档是本任务规格的唯一权威来源（2026-11-25 用户提供并确认）。后续所有会话（含定时续做）必须以本文 + <a href="./parity-progress">parity-progress.md</a> 为准，用 <code>git tag</code> / <code>git log</code> 核对真实进度，不信任何口头声称。 基线：<strong>v3.10.2</strong>（main = b683ede8）。官方对照对象：官方 <code>Escrcpy-3.3.1</code> 付费闭源全功能二进制。</p></blockquote><h2 id="_0-铁律-违反任意一条-任务失败" tabindex="-1">0. 铁律（违反任意一条 = 任务失败） <a class="header-anchor" href="#_0-铁律-违反任意一条-任务失败" aria-label="Permalink to &quot;0. 铁律（违反任意一条 = 任务失败）&quot;">​</a></h2><ul><li>仓库 <code>cshdotcom/escrcpy-Next</code>，分支 main；允许 <code>feat/*</code> 分支，合并前必须 build + 图标门禁 + e2e 全绿。</li><li><strong>增量交付</strong>：每完成一个模块 → <code>commit</code> → 打 tag → <code>push</code> → 触发 CI → 验证三平台资产可下载。沙箱随时被回收，未推送的代码等于丢失；单阶段内的中途成果用 <code>snapshot/*</code> tag 保护。</li><li><strong>禁止&quot;文案在、功能没做&quot;</strong>：每个功能必须同时具备 ①UI 入口 ②IPC/HTTP 接口 ③执行路径 ④e2e 断言。只加 locale key、只加常量、只加按钮都算未完成。</li><li><strong>不许回退已有能力</strong>：v3.7.0–v3.10.2 已有的（EIO 守卫、配置持久化、离线自愈、自动重连、错误隔离、上下文压缩、群控广播、多设备 AI、OpenCV 识图前置、网页三页签、镜像 WebCodecs、工作流画布、多屏协同、单 data 消费者架构…）一个都不许丢，改到就补 e2e。</li><li>代码注释英文；UI 文案走 i18n（en-US / zh-CN / zh-TW 三份必须同步，<code>pnpm lang-sync</code> 校验）。</li><li>本地环境与 CI 对齐：<code>corepack prepare pnpm@12.21.0 --activate</code> + <code>pnpm install --frozen-lockfile</code> + <code>pnpm exec turbo build</code> + <code>node scripts/check-icons.js</code>。<strong>lockfile 是 pnpm 12 双文档格式，不许剥离。</strong></li></ul><h2 id="_1-官方基准-v3-3-1-付费闭源功能清单-验收对照表" tabindex="-1">1. 官方基准：v3.3.1 付费闭源功能清单（验收对照表） <a class="header-anchor" href="#_1-官方基准-v3-3-1-付费闭源功能清单-验收对照表" aria-label="Permalink to &quot;1. 官方基准：v3.3.1 付费闭源功能清单（验收对照表）&quot;">​</a></h2><blockquote><p>官方 deb → <code>resources/app.asar</code>（标准 asar）。官方 locale（zh-CN.json，1305 条）是功能点权威清单；付费页面文案内嵌在页面 bundle 中。公开源码只有 control / explorer / terminal 三页；<strong>automation / mirror / copilot 是闭源付费模块，只能逆向二进制，不是比对源码。</strong></p></blockquote><h3 id="_1-1-官方「自动化脚本编辑器」-automation-页-170-条文案" tabindex="-1">1.1 官方「自动化脚本编辑器」（automation 页，170 条文案） <a class="header-anchor" href="#_1-1-官方「自动化脚本编辑器」-automation-页-170-条文案" aria-label="Permalink to &quot;1.1 官方「自动化脚本编辑器」（automation 页，170 条文案）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>官方细节</th></tr></thead><tbody><tr><td>脚本管理</td><td>脚本列表、新建、删除（二次确认）、保存、按设备选择、空态提示</td></tr><tr><td>导入导出</td><td>导入（替换全部步骤需确认）、导出、无脚本提示</td></tr><tr><td>步骤类型</td><td>tap / swipe（起终点、时长、距离）/ input / key（键值可选可填）/ wait / launch（包名或已装 App，<strong>启动前强制停止</strong>）/ install（APK 路径，<strong>安装前先卸载</strong>）/ screenshot（自动命名、保存目录）/ record（屏幕或摄像头、时长、高级设置）/ command（shell，设备 ID 自动加前缀）</td></tr><tr><td>步骤分组</td><td>基础操作 / 条件操作 / 扩展操作</td></tr><tr><td>步骤公共字段</td><td>name、delayBefore、loopCount、randomRange（坐标 n×5px、时间 n×500ms、0=禁用）、target.by / target.value、前插入 / 后插入、高级设置折叠区</td></tr><tr><td>识图判断</td><td>任意步骤可挂 imageMatch：模板区域选择、重新裁剪、预览、阈值、<strong>匹配点跟随</strong>、模板缺失提示、未匹配跳过、裁剪中心填入 tap 坐标</td></tr><tr><td>智能拾取</td><td>实时截图上：拖拽裁剪模板、单击取坐标、拖拽画滑动轨迹、无选区提示、截屏失败错误</td></tr><tr><td>执行控制</td><td>单步 / 执行选中 / 全量 / 暂停 / 继续 / 停止；切换脚本先停；状态机 idle/running/paused/stopped；无设备/无步骤提示</td></tr><tr><td>执行日志</td><td>独立面板、清空、空态、完成/失败/已终止/已暂停/已恢复/已停止逐条反馈</td></tr><tr><td>批量执行</td><td>变量注入表格、添加行、执行、终止、执行中、完成提示</td></tr><tr><td>魔法变量</td><td>自定义变量 CRUD（名称校验、重名校验、描述）、内置变量（date=YYYY-MM-DD、deviceId、stepIndex、timestamp ms）、<code>{varName}</code> 语法、插入弹窗、只读、示例</td></tr><tr><td>模板库</td><td>打开 App / 账号登录 / 批量截图 / 微信发消息（含完整步骤），「从模板创建」「应用模板」</td></tr><tr><td>内置按键</td><td>返回/删除/回车/主页/菜单/电源/最近任务/音量加减</td></tr></tbody></table><h3 id="_1-2-官方「群控镜像」-mirror-页-31-条文案-通道表" tabindex="-1">1.2 官方「群控镜像」（mirror 页，31 条文案 + 通道表） <a class="header-anchor" href="#_1-2-官方「群控镜像」-mirror-页-31-条文案-通道表" aria-label="Permalink to &quot;1.2 官方「群控镜像」（mirror 页，31 条文案 + 通道表）&quot;">​</a></h3><ul><li>一个镜像窗口承载 N 台设备（<code>mirror.devices</code>），顶部「打开所有设备」。</li><li>手势广播：点击/滑动/文字输入并行下发设备组（BROADCAST_TOUCH_EVENT / BROADCAST_KEY_CODE / BROADCAST_SCROLL）。</li><li>首次使用三步操作指引（点击、滑动、输入 → 多台同步），可「不再提示」。</li><li>置顶/取消置顶、全屏/退出全屏、输入条（Enter 发送、关闭）、返回/主页/最近任务快捷键、连接中/已断开/重新连接。</li><li>技术底座（已验证）：主进程 scrcpy 协议栈、WebCodecs optimizeForLatency、CSD 拼接、丢帧保护、konva 键位画布、<code>scrcpy:*</code> IPC 通道表。</li></ul><h3 id="_1-3-官方设备控制栏缺口-device-control-128-条中-14-条未引用" tabindex="-1">1.3 官方设备控制栏缺口（device.control，128 条中 14 条未引用） <a class="header-anchor" href="#_1-3-官方设备控制栏缺口-device-control-128-条中-14-条未引用" aria-label="Permalink to &quot;1.3 官方设备控制栏缺口（device.control，128 条中 14 条未引用）&quot;">​</a></h3><p>多屏协同细节文案、启动应用目标窗口选择（当前窗口=内嵌镜像 / 主显示器 + 启动设置 + 分身用户提示）、音量三项独立命名、截图成功&quot;去查看&quot;、文件管理器全选/反选/取消全选/重命名成功/上传进度/下载失败/推送失败、gnirehtet 停止成功。</p><h3 id="_1-4-官方-ai-copilot" tabindex="-1">1.4 官方 AI（copilot） <a class="header-anchor" href="#_1-4-官方-ai-copilot" aria-label="Permalink to &quot;1.4 官方 AI（copilot）&quot;">​</a></h3><p>闭源，走 api.moark.com 网关。<strong>我们自研版更完整（多供应商、工具循环、定时任务、上下文压缩、多设备），不做 1:1 对照，但必须不弱于官方</strong>：多轮工具调用、视觉回传、会话续聊、用量与错误可见。</p><h2 id="_2-核验方法-每个会话必须重跑-禁止采信既有结论" tabindex="-1">2. 核验方法（每个会话必须重跑，禁止采信既有结论） <a class="header-anchor" href="#_2-核验方法-每个会话必须重跑-禁止采信既有结论" aria-label="Permalink to &quot;2. 核验方法（每个会话必须重跑，禁止采信既有结论）&quot;">​</a></h2><ol><li><strong>文案落地率</strong>（hyphen-aware 版本，见 <code>scripts/</code> 与 parity-report）： <ul><li>基线（2026-11-25 实测）：automation 170 总 / 30 引用 / <strong>140 未引用</strong>；mirror 31 / 5 / <strong>26</strong>；device.control 128 / 114 / <strong>14</strong>。</li><li>目标：automation ≥95% 引用、mirror ≥90%、device.control ≥95%，且每条引用对应真实 UI。</li></ul></li><li><strong>执行器分支清单</strong>：<code>grep -nE &quot;case &#39;&quot; desktop/electron/modules/tasks/helpers/executor.js</code>，与 1.1 对表。 <ul><li>基线（实测 18 种）：broadcast_input_text / broadcast_key / broadcast_screenshot / broadcast_tap / get_device_info / get_ui_layout / http / input_text / key / list_devices / match_image / notify / open_app / screenshot / shell / swipe / tap / wait_image。</li><li>缺：<strong>wait、install、record、loop、condition</strong> 步骤类型 + <strong>launch 强停</strong> + 步骤级 <strong>delayBefore / loopCount / randomRange</strong>。</li></ul></li><li><strong>UI 入口清单</strong>：每个功能在 <code>desktop/pages/**</code> 有组件与交互，不能只出现在常量文件。</li><li><strong>手动跑一遍</strong>：本地 build + e2e（fake adb 双设备），逐功能点验证（官方要求&quot;实际可用&quot;而不是&quot;应该能用&quot;）。</li></ol><h2 id="_3-应用端待补功能-优先级-验收口径" tabindex="-1">3. 应用端待补功能（优先级 + 验收口径） <a class="header-anchor" href="#_3-应用端待补功能-优先级-验收口径" aria-label="Permalink to &quot;3. 应用端待补功能（优先级 + 验收口径）&quot;">​</a></h2><h3 id="p0-a-自动化脚本工作台-v3-11-1" tabindex="-1">P0-A 自动化脚本工作台（v3.11.1） <a class="header-anchor" href="#p0-a-自动化脚本工作台-v3-11-1" aria-label="Permalink to &quot;P0-A 自动化脚本工作台（v3.11.1）&quot;">​</a></h3><p>新页面 <code>desktop/pages/automation/</code>（独立窗口，<strong>注册 vite input</strong>）。数据模型 <code>scripts: [{id, deviceId, name, steps[], variables[], createdAt, updatedAt}]</code> 落 electron-store。布局：左脚本列表 / 中步骤列表（拖拽排序、复制、前后插入、删除、高级折叠）/ 右步骤表单 / 底执行日志。执行引擎：单步/选中/全量/暂停/继续/停止；状态机 idle→running⇄paused→stopped；同脚本不并发；切换先停。步骤统一字段 name/type/delayBefore/loopCount/randomRange/imageMatch/target。导入导出 JSON（导入前确认替换）。 <strong>验收</strong>：假设备跑「启动 App→点击→输入→截图」四步脚本，单步、暂停恢复、日志逐条、导出再导入一致；e2e 覆盖。</p><h3 id="p0-b-补齐步骤类型-v3-11-2" tabindex="-1">P0-B 补齐步骤类型（v3.11.2） <a class="header-anchor" href="#p0-b-补齐步骤类型-v3-11-2" aria-label="Permalink to &quot;P0-B 补齐步骤类型（v3.11.2）&quot;">​</a></h3><p>install（<code>adb install -r</code> + 可选先卸载）、record（screenrecord，屏幕/摄像头、时长、目录）、launch（包名/已装 App + 强停）、loop（子步骤循环）、condition（图像存在/设备在线/变量比较）、wait、command（shell 自动设备前缀）。 <strong>验收</strong>：每类 ≥1 条 e2e + executor 单测；loopCount/randomRange 生效可观测（日志打实际坐标与延时）。</p><h3 id="p1-a-智能拾取-v3-11-3" tabindex="-1">P1-A 智能拾取（v3.11.3） <a class="header-anchor" href="#p1-a-智能拾取-v3-11-3" aria-label="Permalink to &quot;P1-A 智能拾取（v3.11.3）&quot;">​</a></h3><p>实时截图 → 画布拖拽裁剪存模板 + 单击取坐标 + 拖拽画轨迹；重新裁剪、预览、失败给可读错误。 <strong>验收</strong>：裁剪模板直接喂 imageMatch 匹配成功。</p><h3 id="p1-b-魔法变量-批量执行-v3-11-3" tabindex="-1">P1-B 魔法变量 + 批量执行（v3.11.3） <a class="header-anchor" href="#p1-b-魔法变量-批量执行-v3-11-3" aria-label="Permalink to &quot;P1-B 魔法变量 + 批量执行（v3.11.3）&quot;">​</a></h3><p><code>{var}</code> 解析（步骤所有文本字段）、自定义变量 CRUD + 校验、内置变量 date/deviceId/stepIndex/timestamp；批量执行表格（一行一设备 + 变量列）并行下发、终止。 <strong>验收</strong>：同一脚本 2 台设备灌不同变量，日志正确互不串。</p><h3 id="p1-c-官方模板库-v3-11-3" tabindex="-1">P1-C 官方模板库（v3.11.3） <a class="header-anchor" href="#p1-c-官方模板库-v3-11-3" aria-label="Permalink to &quot;P1-C 官方模板库（v3.11.3）&quot;">​</a></h3><p>打开 App / 账号登录 / 批量截图 / 微信发消息 四套模板，「从模板创建」。</p><h3 id="p2-官方级群控与多屏-v3-13-0" tabindex="-1">P2 官方级群控与多屏（v3.13.0） <a class="header-anchor" href="#p2-官方级群控与多屏-v3-13-0" aria-label="Permalink to &quot;P2 官方级群控与多屏（v3.13.0）&quot;">​</a></h3><p>镜像窗口多设备同屏（N 宫格）、主控手势广播全组、「打开所有设备」、三步首用指引；多屏协同 ROM 检测 + 兼容提示；内嵌镜像内启动 App（「在当前窗口打开」）。</p><h2 id="_4-超越官方-必须新增-v3-12-0-起" tabindex="-1">4. 超越官方：必须新增（v3.12.0 起） <a class="header-anchor" href="#_4-超越官方-必须新增-v3-12-0-起" aria-label="Permalink to &quot;4. 超越官方：必须新增（v3.12.0 起）&quot;">​</a></h2><ol><li>自然语言生成脚本（一句话 → 步骤草案，复用 Copilot 供应商栈，可编辑可 dry-run）</li><li>UI 操作录制成脚本（镜像窗口操作录制为步骤，一键转脚本）</li><li>失败诊断与断点续跑（原因分类：设备离线/图像未匹配/权限/超时 + 建议；从失败步骤续跑）</li><li>脚本版本历史（保存留版本，可 diff、可回滚）</li><li>dry-run 预检（设备在线、APK 存在、模板存在、变量齐全，列风险项）</li><li>多设备并行执行 + 每设备独立变量 + 汇总报表（成功/失败/耗时，导出 CSV）</li><li>条件分支可视化（画布 if/else 分叉）</li><li>模板分享码（导出短码/JSON 可导入）</li><li>执行产物归档（截图/录屏按「脚本-设备-时间」归档，可对比两次运行差异）</li><li>AI 复盘（批量执行结束自动总结失败原因与建议，可关）</li></ol><h2 id="_5-网页端-目标-桌面端-90-能力在浏览器可用" tabindex="-1">5. 网页端（目标：桌面端 90% 能力在浏览器可用） <a class="header-anchor" href="#_5-网页端-目标-桌面端-90-能力在浏览器可用" aria-label="Permalink to &quot;5. 网页端（目标：桌面端 90% 能力在浏览器可用）&quot;">​</a></h2><p>现状：对话/自动任务/镜像三个页签（18 个 /api/ 端点）。要补：</p><ol><li>任务/工作流/脚本完整 CRUD（新建、编辑、复制、删除、启停、cron、上下文策略）</li><li>自动化脚本工作台（步骤编辑、单步/暂停/继续、日志、导入导出、变量）</li><li>群控面板（多选设备广播点击/滑动/文字/按键、批量截图、批量装 APK、日志）</li><li>镜像增强（多设备同屏、全屏、键位映射在线编辑、剪贴板、快捷按键）</li><li>对话增强（文件/图片上传、会话重命名/删除/搜索/导出、消息重发/编辑、工具卡片展开）</li><li>运行历史详情（每步耗时、输入输出、失败原因、日志下载）</li><li>供应商设置（baseUrl/model/apiKey 可改，<strong>apiKey 不回显明文</strong>）</li><li>移动端适配（触控、软键盘避让、横屏镜像、单手布局）</li><li>实时性（SSE 断线重连 + 心跳；镜像 WS 重连提示）</li><li>安全（bcrypt 密码、短时 token、失败限流 5 次/分钟、只读模式、可选 HTTPS/仅内网）</li><li>空态/骨架/Toast/深色/i18n（跟随浏览器） <strong>验收</strong>：手机浏览器完成「新建脚本 → 跑 2 台设备 → 看日志 → 截图归档」全流程。</li></ol><h2 id="_6-人性化清单-两端统一验收" tabindex="-1">6. 人性化清单（两端统一验收） <a class="header-anchor" href="#_6-人性化清单-两端统一验收" aria-label="Permalink to &quot;6. 人性化清单（两端统一验收）&quot;">​</a></h2><p>首用四步向导（可跳过）；空列表给「下一步」引导；危险操作二次确认（删脚本/卸载/批量执行/格式化类）；撤销重做（步骤编辑、脚本删除 30 秒恢复）；拖拽排序、复制、批量选择；错误一律&quot;人话+原因+建议+一键重试&quot;；长任务进度条 + 预计剩余 + 可中止；快捷键面板（可查可改）+ WASD 提示；三语言 + 无障碍（键盘可达、aria-label）+ 高对比；日志一键复制/导出。</p><h2 id="_7-验收标准-dod" tabindex="-1">7. 验收标准（DoD） <a class="header-anchor" href="#_7-验收标准-dod" aria-label="Permalink to &quot;7. 验收标准（DoD）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>门槛</th></tr></thead><tbody><tr><td>官方文案落地率</td><td>automation ≥95%、mirror ≥90%、device.control ≥95%（脚本统计 + 每条有 UI 引用）</td></tr><tr><td>步骤类型</td><td>executor case 覆盖 1.1 全部类型，每类 ≥1 e2e</td></tr><tr><td>执行控制</td><td>单步/选中/全量/暂停/继续/停止可用且状态机可观测</td></tr><tr><td>e2e</td><td>新增场景使总数 ≥90，全绿；含双设备并行、暂停恢复、变量注入、拾取匹配</td></tr><tr><td>网页端</td><td>第 5 节 11 项可用，手机端全流程走通</td></tr><tr><td>稳定性</td><td>8 小时定时任务 + 镜像，RSS 增长 &lt;150MB，无未捕获异常</td></tr><tr><td>性能</td><td>镜像端到端延迟 &lt;120ms；100 步脚本编辑输入延迟 &lt;50ms</td></tr><tr><td>兼容</td><td>三平台安装包可下可启动；mac 排队失败按既有 rerun 策略</td></tr><tr><td>文档</td><td>CHANGELOG 按功能列；README 截图用法；每版 release 说明含新增/修复/已知问题</td></tr></tbody></table><h2 id="_8-历史坑-踩过就会失败" tabindex="-1">8. 历史坑（踩过就会失败） <a class="header-anchor" href="#_8-历史坑-踩过就会失败" aria-label="Permalink to &quot;8. 历史坑（踩过就会失败）&quot;">​</a></h2><ol><li>pnpm 12.21.0 lockfile 双文档格式，剥离第一段 = CI frozen-lockfile 必挂；本地也用 pnpm 12。</li><li>新页面必须注册 vite build input，否则开发正常、打包白窗（group-control 踩过；mirror 页已一并注册）。</li><li>solar 图标名先跑 <code>node scripts/check-icons.js</code>（曾 3 个 + 1 个 chat 图标导致 build 门禁 5 连红）。</li><li>rolldown：模块级常量被 DCE 误删（用 export 保护）；re-export 链符号重命名碰撞（显式导入、不用匿名类）。</li><li>scrcpy：视频包 pts <strong>大端</strong>；视频 socket 只能挂<strong>一个</strong> data 消费者（多监听瓜分字节流错帧）。</li><li>adbkit：v1 shell 输出被真实 adb LF→CRLF；<code>screencap</code> 实际是 <code>echo &amp;&amp; screencap -p</code>。</li><li>electron-store 嵌套路径（copilot.settings 是路径不是扁平 key）。</li><li>e2e i18n：生产构建 process.resourcesPath 指向内置目录，按钮 title 是原始 key，断言兼容 key + 中英文。</li><li>改名残留：deviceId→deviceIds 后必须全局 grep（遗漏 = ReferenceError + 消息静默不发）。</li><li>大文件下载必须校验 sha256（官方 deb 真实大小 123,461,804 字节）。</li><li>沙箱会回收后台进程与工作区：安装用 <code>setsid</code> 脱离 + 日志轮询；所有成果及时 push；lockfile/工作成果在 <code>/home/z/my-project/</code> 内。</li><li>Mac 构建机排队超时会复发（v3.9.0、v3.10.2 均遇），按既有 rerun 策略处理。</li></ol><h2 id="_9-交付节奏-每个-tag-独立可回滚" tabindex="-1">9. 交付节奏（每个 tag 独立可回滚） <a class="header-anchor" href="#_9-交付节奏-每个-tag-独立可回滚" aria-label="Permalink to &quot;9. 交付节奏（每个 tag 独立可回滚）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>产出</th></tr></thead><tbody><tr><td>v3.11.0</td><td>第 2 节完整核验报告（官方功能→现状→证据）</td><td>报告 + 差距确认</td></tr><tr><td>v3.11.1</td><td>P0-A 工作台骨架 + 执行控制 + 日志</td><td>tag + e2e</td></tr><tr><td>v3.11.2</td><td>P0-B 缺失步骤类型</td><td>tag + e2e</td></tr><tr><td>v3.11.3</td><td>P1 拾取 + 变量 + 批量 + 模板库</td><td>tag + e2e</td></tr><tr><td>v3.12.0</td><td>超越项 1/2/3/5</td><td>tag + e2e</td></tr><tr><td>v3.12.1</td><td>网页端完整 CRUD + 工作台 + 群控 + 镜像增强</td><td>tag + e2e</td></tr><tr><td>v3.12.2</td><td>网页端安全/移动端/实时性 + 人性化</td><td>tag + e2e</td></tr><tr><td>v3.13.0</td><td>群控镜像多设备同屏 + 多屏协同增强 + 镜像内启动 App</td><td>tag + e2e</td></tr></tbody></table><p>每个 tag：本地 <code>pnpm exec turbo build</code> + 图标门禁 + 单测 + e2e 全绿 → push → CI → 三平台资产可下载 → CHANGELOG 写明对应官方能力。</p><h2 id="_10-最终自检-交付前逐条打勾" tabindex="-1">10. 最终自检（交付前逐条打勾） <a class="header-anchor" href="#_10-最终自检-交付前逐条打勾" aria-label="Permalink to &quot;10. 最终自检（交付前逐条打勾）&quot;">​</a></h2><ul><li>[ ] 官方 1305 条文案逐条问过&quot;在我们哪个页面/按钮/路径实现&quot;；答不出的补齐或标注废弃理由</li><li>[ ] executor case 与官方步骤类型完全对齐（含 install/record/launch forceStop/loop/condition）</li><li>[ ] 每条官方能力在真实（或 fake adb）设备跑通，有截图/日志证据</li><li>[ ] 网页端手机浏览器端到端无&quot;必须回桌面端&quot;断点</li><li>[ ] 所有新增功能的错误路径都试过（设备拔掉/端口占用/模板丢失/变量缺失/权限拒绝）</li><li>[ ] 三平台安装 → 启动 → 连设备 → 跑脚本无弹错</li><li>[ ] 全部功能 i18n 三语，无硬编码</li><li>[ ] 无未提交改动、无未推送提交、无未打 tag 的阶段成果</li></ul>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};